<script lang="ts">
 import { profileFields } from '$lib/import-fields';import { translator } from '$lib/app-i18n';import DataTable from '$lib/components/DataTable.svelte';
 let {data}=$props();let t=$derived(translator(data.lang)),csv=$state(''),filename=$state(''),columns=$state<string[]>([]),mapping=$state<Record<string,string>>({}),rows=$state<Record<string,any>[]>([]),batch=$state(''),message=$state(''),busy=$state(false),committed=$state(false);
 let original=$state(''),profileName=$state(''),selectedProfile=$state(''),profile=$state('opening'),decimalSeparator=$state('.');let fields=$derived(profileFields[profile]);
 function remap(){mapping=Object.fromEntries(fields.map(field=>[field,columns.find(column=>column.toLowerCase()===field)??'']));rows=[];batch='';committed=false;}
 async function file(event:Event){const selected=(event.currentTarget as HTMLInputElement).files?.[0];if(!selected)return;busy=true;message='';try{const form=new FormData();form.set('file',selected);const res=await fetch('/api/import/parse',{method:'POST',body:form});const result=await res.json();if(!res.ok){message=t(result.message);return;}original=result.original_base64??'';csv=result.csv;filename=result.filename;columns=result.columns;remap();}catch{message=t('connectionError');}finally{busy=false;}}
 function applyProfile(){const p=data.profiles.find((p:any)=>p.id===selectedProfile);if(p){profile=p.profile;mapping={...p.mapping};decimalSeparator=p.decimal_separator;rows=[];batch='';}}
 async function saveProfile(){const res=await fetch('/api/import/profiles',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:profileName,profile,mapping,decimal_separator:decimalSeparator})});message=res.ok?t('saved'):t((await res.json()).message);}
 async function preview(){busy=true;try{const res=await fetch('/api/import',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({csv,filename,mapping,profile,decimal_separator:decimalSeparator,original_base64:original||undefined})});const result=await res.json();if(!res.ok){message=result.message;return;}rows=result.rows;batch=result.id;committed=result.state==='committed';message=committed?t('saved'):'';}finally{busy=false;}}
 async function commit(){busy=true;try{const res=await fetch('/api/import',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({batch_id:batch})});const result=await res.json();if(!res.ok){message=result.message;return;}rows=result.report;committed=true;message=t('saved');}finally{busy=false;}}
</script>
<p class="eyebrow">{data.tenant.name}</p><h1>{t('import')}</h1><div class="import-steps" aria-label={t('import')}><div class:current={!columns.length}><span>1</span>{t('uxChooseFile')}</div><div class:current={columns.length>0&&!rows.length}><span>2</span>{t('uxMapColumns')}</div><div class:current={rows.length>0}><span>3</span>{t('uxReviewImport')}</div></div><section class="card"><label>{t('savedProfiles')}<select bind:value={selectedProfile} onchange={applyProfile}><option value="">—</option>{#each data.profiles as p}<option value={p.id}>{p.name} · v{p.revision}</option>{/each}</select></label><div class="mapping"><label>{t('importProfile')}<select bind:value={profile} onchange={remap}>{#each Object.keys(profileFields) as p}<option value={p}>{t(p)}</option>{/each}</select></label><label>{t('decimal_separator')}<select bind:value={decimalSeparator}><option value=".">1.25</option><option value=",">1,25</option></select></label></div><label>CSV · JSON · XLSX<input type="file" accept=".csv,.json,.xlsx" onchange={file} disabled={busy} /></label>{#if columns.length}<form onsubmit={(e)=>{e.preventDefault();preview();}}><div class="mapping">{#each fields as field}<label>{t(field)}<select bind:value={mapping[field]} required={false}><option value="">—</option>{#each columns as column}<option value={column}>{column}</option>{/each}</select></label>{/each}</div><button disabled={busy}>{t('preview')}</button></form><label>{t('profileName')}<input bind:value={profileName} maxlength="160" /></label><button onclick={saveProfile} disabled={busy||!profileName}>{t('saveProfile')}</button>{/if}</section>{#if rows.length}<section class="card"><h2>{committed?t('saved'):t('preview')}</h2>{#if rows.some(row=>row.error)}<p class="notice">{t('uxPartialImport')} ({rows.filter(row=>row.error).length})</p>{/if}<DataTable {rows} lang={data.lang} timezone={data.tenant.timezone} columns={committed?['row','status','error']:['row',...fields,'error']} {t} />{#if batch&&!committed}<button onclick={commit} disabled={busy}>{t('commit')}</button>{/if}</section>{/if}<p role="status">{message}</p><a href="/app/data">{t('data')}</a>
<style>.import-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0}.import-steps>div{display:flex;align-items:center;gap:12px;padding:16px;border:1px solid var(--line);background:white;border-radius:10px;font-size:12px;color:var(--muted)}.import-steps>div.current{background:var(--tint);color:var(--brand);border-color:#bad8c5}.import-steps span{width:26px;height:26px;border-radius:50%;background:#eef3ef;display:grid;place-items:center;font-size:11px;font-weight:650}.import-steps .current span{background:var(--brand);color:white}@media(max-width:640px){.import-steps{gap:6px}.import-steps>div{padding:12px 8px;flex-direction:column;text-align:center;font-size:10px}}.mapping{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:22px 0}button{margin-top:16px}</style>
